/**
 * Export parity: the plugin's designer must produce the same files as the
 * upstream CLI for the same `.box.json`.
 *
 * Both sides call the vendored `uiToml()` / `panelSvg()`, so this is really a
 * guard against the vendored copy drifting from the upstream checkout when it is
 * updated. Two modes:
 *
 *   - always: compare against the committed fixture (`test/fixtures/*.ui.toml`),
 *     regenerated by `node test/export-parity.mjs --refresh`;
 *   - when `BOX_DESIGNER_DIR` (or /tmp/rustomp-box-designer) exists: also run the
 *     upstream CLI live and require byte equality.
 */
import { readFileSync, writeFileSync, existsSync, mkdtempSync, rmSync } from 'node:fs'
import { execFileSync } from 'node:child_process'
import { tmpdir } from 'node:os'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

import { load, mergedAssets } from '../vendor/boxdesigner/model.js'
import { panelSvg, uiToml } from '../vendor/boxdesigner/exporter.js'
import { ASSET_TEXT } from '../vendor/boxdesigner/assets.text.js'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = join(HERE, '..')
const FIXTURE = join(HERE, 'fixtures', 'sparklin.box.json')
const EXPECTED_TOML = join(HERE, 'fixtures', 'sparklin.ui.toml')
const EXPECTED_SVG = join(HERE, 'fixtures', 'sparklin.panel.svg')
const UPSTREAM = process.env.BOX_DESIGNER_DIR ?? '/tmp/rustomp-box-designer'
const refresh = process.argv.includes('--refresh')

const doc = load(readFileSync(FIXTURE, 'utf8'))
const actualToml = uiToml(doc)
const actualSvg = panelSvg(doc, mergedAssets(doc, ASSET_TEXT), { controls: false })

if (refresh) {
  writeFileSync(EXPECTED_TOML, actualToml)
  writeFileSync(EXPECTED_SVG, actualSvg)
  console.log(`已刷新夹具：${EXPECTED_TOML}、${EXPECTED_SVG}`)
}

const failures = []

/**
 * Record one comparison.
 * @param label - what was compared.
 * @param actual - produced text.
 * @param expected - expected text.
 */
function expectEqual(label, actual, expected) {
  if (actual === expected) {
    console.log(`  ✓ ${label}（${actual.length} 字节）`)
    return
  }
  const line = actual.split('\n').findIndex((text, index) => text !== expected.split('\n')[index])
  failures.push(`${label} 不一致，首个不同行 ${line + 1}`)
  console.log(`  ✗ ${label}：第 ${line + 1} 行不同`)
}

console.log('== 与提交的夹具比对 ==')
expectEqual('ui.toml', actualToml, readFileSync(EXPECTED_TOML, 'utf8'))
expectEqual('panel.svg', actualSvg, readFileSync(EXPECTED_SVG, 'utf8'))

if (existsSync(join(UPSTREAM, 'scripts/export.mjs'))) {
  console.log(`== 与上游 CLI 活体比对（${UPSTREAM}）==`)
  const out = mkdtempSync(join(tmpdir(), 'c2v-parity-'))
  try {
    execFileSync(process.execPath, [join(UPSTREAM, 'scripts/export.mjs'), FIXTURE, '--out', out, '--svg-only'], {
      stdio: 'pipe',
    })
    expectEqual('上游 ui.toml', actualToml, readFileSync(join(out, 'ui.toml'), 'utf8'))
    expectEqual('上游 panel.svg', actualSvg, readFileSync(join(out, 'panel.svg'), 'utf8'))
  } finally {
    rmSync(out, { recursive: true, force: true })
  }
} else {
  console.log(`（跳过活体比对：没有 ${UPSTREAM}，设 BOX_DESIGNER_DIR 可开启）`)
}

if (failures.length > 0) {
  console.error(`\n✗ ${failures.length} 处不一致：\n  - ${failures.join('\n  - ')}`)
  process.exit(1)
}
console.log('\n全部一致：插件导出的 ui.toml / panel.svg 与上游相同')
